  beforeDestroy() {
    this.stopVideo()
  },
  destroyed() {
    this.stopVideo()
  },
  methods: {
    async initializePlayers(videoUrls) {
      await this.$nextTick(); // 确保 DOM 已经更新

      videoUrls.forEach(({ flv_url, ref }) => {
        this.playVideo(flv_url, ref);
      });
    },
    playVideo(url, refName) {
      console.log(`Initializing video with URL: ${url} and ref: ${refName}`);

      //   const videoElement = this.$refs[refName];
      const videoElement = document.getElementById(refName);
      if (!videoElement || !(videoElement instanceof HTMLVideoElement)) {
        console.error('无法找到有效的 video 元素:', videoElement);
        return;
      }

      // 如果已经存在 FLV 播放器实例，先销毁当前的播放器
      if (this.flvPlayers[refName] && typeof this.flvPlayers[refName].destroy === 'function') {
        try {
          this.flvPlayers[refName].destroy();
        } catch (error) {
          console.error('销毁 FLV 播放器时出错:', error);
        }
      }

      // 创建新的 FLV 播放器实例
      try {
        const player = flvjs.createPlayer({
          type: 'flv',
          url: url, // 你的 FLV 流地址
        });

        // 将新的播放器绑定到视频元素
        player.attachMediaElement(videoElement);

        // 开始加载和播放新的视频
        player.load();
        player.play();

        // 添加事件监听以处理播放器生命周期中的重要事件
        player.on(flvjs.Events.ERROR, (errType, errDetail) => {
          console.error(`FLV 播放器 (${refName}) 发生错误:`, errType, errDetail);
        });
        player.on(flvjs.Events.LOADING_COMPLETE, () => {
          console.log(`FLV 播放器 (${refName}) 加载完成`);
        });
        player.on(flvjs.Events.PLAYING, () => {
          console.log(`FLV 播放器 (${refName}) 开始播放`);
        });

        // 存储播放器实例
        this.flvPlayers[refName] = player;
      } catch (error) {
        console.error(`创建或绑定 FLV 播放器 (${refName}) 时出错:`, error);
      }
    },
    // 播放视频函数
    // playVideo(url) {
    //   // 检查浏览器是否支持 FLV.js
    //   if (flvjs.isSupported()) {
    //     // 获取视频元素
    //     const videoElement = this.$refs['videoPlayer11'];
    //     console.log(videoElement)

    //     // 如果已经存在 FLV 播放器实例，先销毁当前的播放器
    //     if (this.flvPlayer && this.flvPlayer.destroy) {
    //       this.flvPlayer.destroy();
    //     }

    //     // 创建新的 FLV 播放器实例
    //     this.flvPlayer = flvjs.createPlayer({
    //       type: 'flv',
    //       url: url, // 你的 FLV 流地址
    //     });

    //     // 将新的播放器绑定到视频元素
    //     this.flvPlayer.attachMediaElement(videoElement);

    //     // 开始加载和播放新的视频
    //     this.flvPlayer.load();
    //     this.flvPlayer.play();
    //   } else {
    //     this.$message.warning('浏览器不支持 FLV.js');
    //   }
    // },
    playVideo2() {
      // 如果已经存在 FLV 播放器实例，先销毁当前的播放器
      if (this.flvPlayer && this.flvPlayer.destroy) {
        this.flvPlayer.destroy();
      }
      const videoElement = this.$refs.videoPlayer;

      // 设置视频的 src
      videoElement.src = '/static/img/video/AIspfx.mp4';

      // 播放视频
      videoElement.play();
    },
    validateEndTime(rule, value, callback) {
      if (this.queryParams.start_time && value) {
        if (new Date(this.queryParams.start_time) >= new Date(value)) {
          callback(new Error('结束时间必须在开始时间之后'));
        } else {
          callback();
        }
      } else {
        callback();
      }
    },
    // 搜索视频并播放视频
    getVideo() {
      this.$http.get(spfxApi.getPlayInfo, {
        params: {
          rtsp_url: this.queryParams.monitorPoint,
          model_id: this.queryParams.model_id,
          width: this.queryParams.resolution.width,
          det_type: 1,
          height: this.queryParams.resolution.height,
          baud_b: this.queryParams.bitRate,
          frame_r: this.queryParams.frameRate,
          stream_data_flag: 1,
          em_id: JSON.stringify([this.queryParams.em_id]),
          //   em_id: JSON.stringify([2, 3, 4, 5]),
          video_status: this.activeName == 'preview' ? 1 : 2,
          start_time: this.activeName == 'playback' ? this.formatDate(this.queryParams.start_time) : null,
          end_time: this.activeName == 'playback' ? this.formatDate(this.queryParams.end_time) : null,
        }
      }).then(response => {
        if (response.data.code === 200) {
          this.$message.success(response.data.msg);
          //   this.videoLoading = true
          //   this.playVideo(response.data.flv_data[0].flv_url,'videoPlayer11')
          //   this.playVideo(response.data.flv_data[1].flv_url,'videoPlayer12')
          //   this.playVideo(response.data.flv_data[2].flv_url,'videoPlayer21')
          //   this.playVideo(response.data.flv_data[3].flv_url,'videoPlayer22')
          this.$nextTick().then(() => {
            const videoUrls = [
              { flv_url: response.data.flv_data[0].flv_url, ref: 'videoPlayer11' },
              //   { flv_url: response.data.flv_data[1].flv_url, ref: 'videoPlayer12' },
              //   { flv_url: response.data.flv_data[2].flv_url, ref: 'videoPlayer21' },
              //   { flv_url: response.data.flv_data[3].flv_url, ref: 'videoPlayer22' }
            ];

            this.initializePlayers(videoUrls);
          });

          // this.playVideo2()
          // this.playVideo(response.data.flv_url);
          //   this.interTime = setInterval(() => {
          //     this.getFlvStatus()
          //   }, 1000)
        }
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 获取flv状态
    getFlvStatus() {
      this.$http.get(spfxApi.getFlvStatus)
        .then(response => {
          if (response.data.code == 200) {
            clearInterval(this.interTime)
            setTimeout(() => {
              this.playVideo(response.data.video_type)
              this.videoLoading = false
            }, 3000)
          }
        })
        .catch(rek => {
          console.log(rek)
        })
    },
    formatDate(input) {
      // 使用正则表达式将日期格式从 "YYYY-MM-DD HH:MM:SS" 转换为 "YYYYMMDDtHHMMSS"
      return input.replace(/(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})/, '\$1\$2\$3t\$4\$5\$6');
    },
    // 获取监控点列表
    getListPlace() {
      this.$http
        .get(this.$url.url_5000 + "/model_view/equipment_show", {
          params: {
            equipment_name: '',
            equipment_type: '',
            page: 1,
            per_page: 999999999,
          },
        })
        .then((response) => {
          // console.log("监控点列表", response.data.data_list.data.data);
          if (response.data.code === 200) {
            this.HKmenu = response.data.data_list.data;
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    hadnleChangeMKmenu(item) {
      if (item.equipment_type == '录像机') {
        if (item.online == 1) {
        //   this.queryParams.monitorPoint = item.rtsp;
        //   this.queryParams.em_id = item.id;
            
        } else {
          this.queryParams.monitorPoint = '';
          this.queryParams.em_id = '';
          this.$message({
            type: 'warning',
            message: '该监控点不在线,请选择其他监控点!'
          })
        }
      } else {//不是录像机的情况下，现在没有在线状态
        // this.queryParams.monitorPoint = item.rtsp;
        // this.queryParams.em_id = item.id;
      }
