    // 查找当前满足条件的video容器
    getVideoId() {
      // 计算当前有多少个盒子
      let count = Number(this.videoIdNum1) * Number(this.videoIdNum2)
      for (let i = 0; i < count; i++) {
        if (this.videoPlayId[i].type == false) {
          let id = this.videoPlayId[i].id
          let res = this.videoPlay.findIndex(v => v.id == id)
          if (res != -1) {
            return { id, index: i, indexName: res }
          }
        }
      }
      return { id: 'videoId11', index: 0, indexName: 0 };
    },
    // getVideoBoxKong
    handleSearch() {
      // 表单验证通过后执行搜索逻辑
      this.$refs.form.validate((valid) => {
        if (valid) {
          if (this.queryParams.monitorPoint == '') {
            this.$message({
              type: 'warning',
              message: '请选择监控点'
            })
            return
          }
          this.getVideo();
        } else {
          console.log('表单验证失败');
          return false;
        }
      });
    },
    handleStopSearch() {
      this.$http.get(spfxApi.getPlayInfo, {
        params: {
          rtsp_url: this.queryParams.monitorPoint,
          width: this.queryParams.resolution.width,
          height: this.queryParams.resolution.height,
          baud_b: this.queryParams.bitRate,
          det_type: 1,
          frame_r: this.queryParams.frameRate,
          stream_data_flag: 3,
          em_id: this.queryParams.em_id,
          video_status: this.activeName == 'preview' ? 1 : 2,
          start_time: this.activeName == 'playback' ? this.formatDate(this.queryParams.start_time) : null,
          end_time: this.activeName == 'playback' ? this.formatDate(this.queryParams.end_time) : null,
        }
      }).then(response => {
        if (response.data.code === 200) {
          this.$message.success('停止成功');
        }
        // this.flvPlayer.destroy();
        this.playVideo2()
      }).catch(rek => {
        console.log(rek)
      })
    },
    stopVideo() {
      clearInterval(this.interTime)
      this.$http.get(spfxApi.stopVideoSpfx, {
        params: {
          stream_data_flag: 3
        }
      }).then(response => {
        if (response.data.code === 200) {
          // this.$message.success('停止成功');
          this.playVideo2()
          this.videoLoading = false
          clearInterval(this.interTime)
        }
      }).catch(rek => {
        console.log(rek)
        this.videoLoading = false
        clearInterval(this.interTime)
      })
    },
    // 可选的视频布局
    handleChangeLayout() {
      // console.log(this.layout.split('x'))
      let arr = this.layout.split('x')
      this.videoIdNum1 = Number(arr[0])
      this.videoIdNum2 = Number(arr[1])

      //   // 播放状态存储
      //   let videoPlayId = []
