      //     if (!res) {
      //       this.videoPlay[i].videoName = ''
      //     }
      //   }
      //   console.log("videoPlay数据检查", this.videoPlay)
    },
    handleCloseVideoBox(id) {
      // console.log(id)
      // console.log(this.$refs[id])
      // console.log(this.videoPlay)
      let index = this.videoPlay.findIndex(v => v.id == id)
