      return refName;
    },
    // 生成一个id
    generateUniqueId(prefix) {
      // 获取当前时间戳（毫秒）
      const timestamp = Date.now();
      // 生成一个0到9999之间的随机整数
      const randomPart = Math.floor(Math.random() * 10000).toString().padStart(4, '0');

      // 拼接成最终的唯一 ID
      const uniqueId = `${prefix}${timestamp}${randomPart}`;
      return uniqueId;
    },
